import { ListenerNode } from '../listener-node';
import { AbstractState } from './abstract-state';

export class DispatchingState extends AbstractState {
    public removeListenerNode(listenerNode: ListenerNode): void {
        super.removeListenerNode(listenerNode);
        this.stateData.listenerNodePool.removeNodeFromFlow(listenerNode);
    }

    public addListenerNode(listenerNode: ListenerNode): void {
        listenerNode.previous = this.stateData.queueTail;
        this.stateData.queueTail = listenerNode;
    }
}
